/**
 * [INPUT]: 依赖共享房型/家具/模型真源快照、selects 下拉、comparison 同坐标系预览和现行品牌样式
 * [OUTPUT]: 对外提供统一检查器、锚定编辑层、直接拖拽比较、模型多选与结果切换
 * [POS]: sidebar 的单方向收敛原型，独立于原三方向页面与生产代码
 * [PROTOCOL]: 变更时更新此头部，然后检查 CLAUDE.md
 */
import {state,selection,esc,roomStyle,furniture,styleChoices,modelChoices,select} from './shared.js';
import {comparison} from './comparison.js';
import {initSelects} from './selects.js';
const app=document.querySelector('#focus-app');
let editing=null, full=false, drag=null, objectURLs=new Set();
const names={room:'房间类型',furniture:'家具需求',style:'设计风格',models:'出图模型',advanced:'高级设置'};
const arrow='<svg viewBox="0 0 16 16" aria-hidden="true"><path d="m6 4 4 4-4 4"/></svg>';
function row(key,value,description=''){return `<button class="setting-row" data-edit="${key}" aria-expanded="${editing===key}" aria-controls="editor"><span>${names[key]}</span><span class="setting-value">${esc(value)}${description?`<small>${esc(description)}</small>`:''}</span>${arrow}</button>`;}
function editor(){if(!editing)return '';const content={room:roomStyle,furniture,style:styleChoices,models:modelChoices,advanced:()=>`<label class="field">Flux 负向提示词<textarea data-negative placeholder="留空使用系统默认">${esc(state.negative||'')}</textarea></label><p class="helper">填写后整段覆盖，仅影响 Flux2 Klein。</p>`}[editing]();return `<section class="editor" id="editor" role="dialog" aria-label="${names[editing]}" tabindex="-1"><div class="editor-head"><h2>${names[editing]}</h2><button class="text-button" data-close>完成</button></div>${content}<div class="editor-status" role="status"></div></section>`;}
function render(){const s=selection();const models=state.models.length===1?state.models[0]:`${state.models.length} 个模型`;return `<div class="focus-shell"><header class="topbar"><b>Canvas Lab</b><nav class="top-nav"><a class="active" href="focus.html">生图工作台</a><a href="/beta.html" target="_blank">Beta跑图</a><a href="/benchmark.html" target="_blank">模型评测</a></nav><span class="prototype-label">交互原型</span></header><div class="focus-workspace"><aside class="inspector"><div class="inspector-scroll"><div class="inspector-title"><h1>空房设计</h1><span>设计设置</span></div><label class="source-image">${state.image?`<img src="${state.image}" alt="空房原图">`:'<span class="upload-plus">＋</span>'}<span><strong>${state.image?'空房原图':'添加空房照片'}</strong><small>${state.image?'点击替换':'PNG / JPEG / WebP'}</small></span><input type="file" accept="image/png,image/jpeg,image/webp" data-file="image" aria-label="更换空房原图"></label><div class="setting-group">${row('room',state.room)}${row('furniture',s.items.length?`${s.items.length} 项已选`:'自主搭配',s.items.slice(0,3).join('、')+(s.items.length>3?'…':''))}${row('style',state.style)}</div><label class="reference-row">${state.reference?'<span>风格参考已添加 · 点击替换</span>':'<span>＋ 添加风格参考</span>'}<input type="file" accept="image/png,image/jpeg,image/webp" data-file="reference" aria-label="添加风格参考图"></label><label class="notes-label">补充要求 <span>选填</span><textarea data-notes placeholder="例如：保留通道，不要电视">${esc(state.notes)}</textarea></label></div><div class="output-area">${row('models',models,state.models.length>1?'每模型各 1 张':'可多选')}<div class="parameters">${select('resolution','分辨率',['1K','2K'])}${state.models.length===1?select('count','生成张数',['1 张','2 张','3 张','4 张']):'<div class="field"><span>生成张数</span><strong>'+state.models.length+' 张</strong></div>'}<button class="advanced-button" data-edit="advanced" aria-label="高级设置">···</button></div><div class="generation-actions"><button class="generate-button" data-generate aria-label="开始生成"><span class="button-label">START</span></button></div><p class="execution-note">原型演示，不消耗核豆</p></div></aside><main class="preview ${full?'fullscreen':''}"><div class="preview-head"><span class="preview-title">${state.generated?'设计结果':'效果预览'}</span><div class="view-switch" role="group" aria-label="预览方式">${['原图','左右对比','生成结果'].map(v=>`<button data-view="${v}" aria-pressed="${state.view===v}">${v==='左右对比'?'对比':v==='生成结果'?'结果':v}</button>`).join('')}</div><div class="preview-actions"><button class="icon-button" data-full aria-label="${full?'退出放大':'放大预览'}">${full?'↙':'⤢'}</button><details class="image-menu"><summary aria-label="图片操作">···</summary><div><label>载入结果图<input type="file" accept="image/png,image/jpeg,image/webp" data-file="after" aria-label="载入结果图"></label><button data-center>对比分界居中</button><button data-sample>恢复示例图片</button></div></details></div></div><div class="preview-canvas">${state.image?comparison():'<div class="canvas-empty">从左侧添加一张空房照片</div>'}</div><div class="preview-bottom"><span>${state.sample?'空间示意图 · 非实际生成':'原图与结果使用相同画幅对齐'}</span><span>${state.view==='左右对比'&&state.after?'拖动分界线查看变化':''}</span></div>${state.generated&&state.resultItems.length>1?`<div class="filmstrip">${state.resultItems.map((item,n)=>`<button data-result="${n}" aria-pressed="${state.resultIndex===n}"><img src="${item.image}" alt=""><span>${esc(item.model)}</span></button>`).join('')}</div>`:''}</main></div>${editor()}<div class="notice" role="status" hidden></div></div>`;}
function sizePreview(){const frame=app.querySelector('.compare-frame');if(!frame)return;const parent=frame.parentElement;const [w,h]=(state.imageRatio||'3 / 2').split('/').map(Number);const ratio=w/h;const width=Math.min(parent.clientWidth-48,(parent.clientHeight-32)*ratio);frame.style.width=Math.max(0,width)+'px';frame.style.height=Math.max(0,width/ratio)+'px';frame.style.setProperty('--split',state.compare+'%');}
function placeEditor(){const panel=app.querySelector('.editor');if(!panel)return;const trigger=app.querySelector(`[data-edit="${editing}"]`);if(!trigger)return;const r=trigger.getBoundingClientRect();const width=Math.min(348,innerWidth-32);panel.style.width=width+'px';panel.style.left=Math.max(16,Math.min(r.right+12,innerWidth-width-16))+'px';panel.style.top=Math.max(16,Math.min(r.top-12,innerHeight-panel.offsetHeight-16))+'px';panel.style.transformOrigin='left '+Math.max(16,r.top-parseFloat(panel.style.top)+r.height/2)+'px';}
function paint(focusKey){const oldTop=app.querySelector('.inspector-scroll')?.scrollTop||0;app.innerHTML=render();initSelects('#focus-app');app.querySelector('.inspector-scroll').scrollTop=oldTop;sizePreview();placeEditor();if(focusKey)app.querySelector(focusKey)?.focus({preventScroll:true});}
function closeEditor(){const previous=editing;editing=null;paint(previous?`[data-edit="${previous}"]`:null);}
function message(text){const el=app.querySelector('.editor-status')||app.querySelector('.notice');el.textContent=text;el.hidden=false;if(el.classList.contains('notice'))setTimeout(()=>{if(el.isConnected)el.hidden=true;},2600);}
function openEditor(key){if(editing===key){closeEditor();return;}editing=key;paint();const panel=app.querySelector('.editor');panel.focus({preventScroll:true});if(!matchMedia('(prefers-reduced-motion: reduce)').matches)panel.animate([{opacity:0,transform:'translateX(-5px) scale(.985)'},{opacity:1,transform:'translateX(0) scale(1)'}],{duration:160,easing:'cubic-bezier(.2,.8,.2,1)'});}
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.edit){openEditor(b.dataset.edit);return;}if(b.hasAttribute('data-close')){closeEditor();return;}
 if(b.dataset.room){state.room=b.dataset.room;closeEditor();return;}if(b.dataset.style){state.style=b.dataset.style;closeEditor();return;}
 if(b.dataset.item){const s=selection(),item=b.dataset.item;if(item==='其他'){s.custom=!s.custom;if(!s.custom)s.other='';}else s.items=s.items.includes(item)?s.items.filter(x=>x!==item):[...s.items,item];paint(`[data-item="${item}"]`);return;}
 if(b.dataset.model){const m=b.dataset.model;if(state.models.includes(m)){if(state.models.length===1){message('至少保留一个模型');return;}state.models=state.models.filter(x=>x!==m);}else{if(state.models.length===4){message('最多同时选择 4 个模型');return;}state.models.push(m);}if(state.models.length>1)state.count='1 张';paint(`[data-model="${m}"]`);return;}
 if(b.dataset.view){state.view=b.dataset.view;paint();return;}if(b.hasAttribute('data-center')){state.compare=50;paint();return;}if(b.hasAttribute('data-full')){full=!full;paint('[data-full]');return;}
 if(b.dataset.result!==undefined){state.resultIndex=+b.dataset.result;state.after=state.resultItems[state.resultIndex].image;paint();return;}
 if(b.hasAttribute('data-sample')){state.image='./sample-before.svg';state.after='./sample-after.svg';state.imageRatio='3 / 2';state.sample=true;state.generated=false;state.compare=50;state.view='左右对比';paint();return;}
 if(b.hasAttribute('data-generate')){if(!state.image){message('先添加一张空房照片');return;}if(!state.after){message('此原型不调用模型，可在图片操作中载入结果图');return;}editing=null;state.generated=true;state.resultItems=state.models.flatMap(m=>Array.from({length:state.models.length===1?parseInt(state.count):1},(_,n)=>({model:m+(state.models.length===1?' · '+(n+1):''),image:state.after})));state.resultIndex=0;state.view='左右对比';paint();message('已演示完成状态，图片未重新生成');}
});
app.addEventListener('input',e=>{if(e.target.matches('[data-notes]'))state.notes=e.target.value;if(e.target.matches('[data-negative]'))state.negative=e.target.value;if(e.target.matches('[data-other]'))selection().other=e.target.value;if(e.target.matches('[data-compare]'))setSplit(+e.target.value);});
app.addEventListener('change',e=>{if(e.target.dataset.field){state[e.target.dataset.field]=e.target.value;paint();}if(e.target.dataset.file)load(e.target.files[0],e.target.dataset.file);});
function load(file,key){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){message('支持 PNG、JPEG 和 WebP 图片');return;}const url=URL.createObjectURL(file);objectURLs.add(url);const image=new Image();image.onload=()=>{if(objectURLs.has(state[key])){URL.revokeObjectURL(state[key]);objectURLs.delete(state[key]);}state[key]=url;if(key==='image'){state.imageRatio=image.naturalWidth+' / '+image.naturalHeight;state.after='';state.view='原图';}if(key==='after')state.view='左右对比';if(key!=='reference'){state.generated=false;state.sample=false;}paint();};image.onerror=()=>{URL.revokeObjectURL(url);objectURLs.delete(url);message('图片无法读取，请选择另一张图片');};image.src=url;}
function setSplit(value){state.compare=Math.min(100,Math.max(0,value));const frame=app.querySelector('.compare-frame'),input=app.querySelector('[data-compare]');if(frame)frame.style.setProperty('--split',state.compare+'%');if(input){input.value=state.compare;input.setAttribute('aria-valuetext',`原图显示 ${Math.round(state.compare)}%`);}}
// --- 对比直接操作：保留抓取偏移，捕获指针，松手不增加惯性 ---
app.addEventListener('pointerdown',e=>{if(editing&&!e.target.closest('.editor,[data-edit]')){editing=null;app.querySelector('.editor')?.remove();app.querySelectorAll('[data-edit]').forEach(el=>el.setAttribute('aria-expanded','false'));}const input=e.target.closest('[data-compare]');if(!input||e.button!==0)return;const rect=input.getBoundingClientRect();const actual=rect.left+rect.width*state.compare/100;const offset=Math.abs(e.clientX-actual)<24?e.clientX-actual:0;drag={id:e.pointerId,input,rect,offset};input.setPointerCapture(e.pointerId);input.focus({preventScroll:true});e.preventDefault();setSplit((e.clientX-rect.left-offset)/rect.width*100);});
app.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;setSplit((e.clientX-drag.rect.left-drag.offset)/drag.rect.width*100);});
function endDrag(e){if(drag?.id!==e.pointerId)return;if(drag.input.hasPointerCapture(e.pointerId))drag.input.releasePointerCapture(e.pointerId);drag=null;}
app.addEventListener('pointerup',endDrag);app.addEventListener('pointercancel',endDrag);
app.addEventListener('keydown',e=>{if(e.key==='Escape'){if(editing){e.preventDefault();closeEditor();}else if(full){full=false;paint('[data-full]');}}});
app.addEventListener('dragover',e=>{if(e.target.closest('.source-image,.preview-canvas'))e.preventDefault();});app.addEventListener('drop',e=>{if(!e.target.closest('.source-image,.preview-canvas'))return;e.preventDefault();load(e.dataTransfer.files[0],'image');});
window.addEventListener('resize',()=>{sizePreview();placeEditor();});paint();
